/* From Uiverse.io by d4niz - Tags: loader */
.__UIV_SCOPE__ .loader {
  width: 56px;
  height: 56px;
  display: grid;
  border: 4.6px solid #0000;
  border-radius: 100%;
  border-color: #008cff #0000;
  animation: spinner-e04l1k 1.5s infinite linear;
}

.__UIV_SCOPE__ .loader::before, .__UIV_SCOPE__ .loader::after {
  content: "";
  grid-area: 1/1;
  margin: 8px;
  border: inherit;
  border-radius: 50%;
}

.__UIV_SCOPE__ .loader::before {
  border-color: #048be6 #0000;
  animation: inherit;
  animation-duration: 0.1s;
}

.__UIV_SCOPE__ .loader::after {
  margin: 2.9px;
}

@keyframes spinner-e04l1k {
  100% {
    transform: rotate(1turn);
  }
}
